import { join } from 'node:path'
import { loadConfigs } from './core/configs'
import { Diagnostics } from './core/diagnostics'
import { emitFiles, reportStale, type GeneratedFile } from './core/emit'
import { componentExample } from './core/examples'
import {
  defaultPropSource,
  loadManifest,
  propertyKey,
  providerSlot,
  type ComponentEntry,
} from './core/manifest'
import { capitalize, toKebabCase, toWords } from './core/naming'

const GENERATED_HEADER = `/**
 * @generated by Cerberus CLI
 * This file is auto-generated. Do not edit this file manually.
 */

`

const REF_URL = 'https://cerberus.digitalu.design/docs/components'

export function generateComponentAPI(entry: ComponentEntry): GeneratedFile[] {
  const {
    name,
    key,
    recipe,
    source,
    arkKey,
    arkName,
    arkMembers,
    providers,
    memberSlots,
    elementParts,
    collectionGeneric,
    forwardProps,
    defaultProps,
    patchable,
    docsSlug,
    primitives: parts,
    rootProvider,
    description,
    abstractions,
    types,
    exports,
    dir: outputDir,
    partOverrides,
  } = entry
  /** A config `parts.<key>.description`, else the derived one */
  const describe = (key: string, derived: string) =>
    partOverrides[key]?.description?.trim() ?? derived
  const isArkUI = source === 'ark'
  const files: GeneratedFile[] = []

  if (isArkUI) {
    const ark = `Ark${arkName}`
    let primitivesCode = `${GENERATED_HEADER}'use client'\n\n`
    // Ark's base props for the generic members, aliased to avoid our own names
    const genericBases = collectionGeneric.map(
      (m) => `type ${arkName}${m}BaseProps as Ark${arkName}${m}BaseProps`,
    )
    primitivesCode += `import { ${[`${arkName} as ${ark}`, ...genericBases].join(', ')} } from '@ark-ui/react/${arkKey}'\n`
    if (collectionGeneric.length > 0) {
      primitivesCode += `import type { CollectionItem } from '@ark-ui/react/collection'\n`
      primitivesCode += `import type { ReactElement } from 'react'\n`
    }
    if (Object.keys(elementParts).length > 0) {
      primitivesCode += `import { ark } from '@ark-ui/react/factory'\n`
    }
    if (Object.keys(patchable).length > 0) {
      primitivesCode += `import type { Patchable } from '../../internal/extract-parts'\n`
    }
    // Members outside the anatomy have no recipe slot; without a recipe nothing does.
    // Those get Panda's `styled()`, not `cerberus()`: Ark parts handle `asChild`
    // themselves, and a second `asChild` layer would skip the part (and the context
    // a Root provides) entirely
    const isProvider = (m: string) => providers.includes(m)
    const needsStyled =
      !recipe ||
      arkMembers.some(
        (m) =>
          m !== 'RootProvider' &&
          !m.endsWith('Context') &&
          !isProvider(m) &&
          !memberSlots[m],
      )
    const jsxImports = [
      'type ComponentProps',
      ...(recipe ? ['createSlotRecipeContext'] : []),
      ...(needsStyled ? ['styled'] : []),
    ]
    primitivesCode += `import { ${jsxImports.join(', ')} } from 'styled-system/jsx'\n`
    if (recipe) {
      primitivesCode += `import { ${recipe} } from 'styled-system/recipes'\n`
    }
    primitivesCode += `\n`
    if (recipe) {
      const factories = [
        ...(rootProvider ? ['withRootProvider'] : []),
        ...(!rootProvider || providers.length > 0 ? ['withProvider'] : []),
        'withContext',
      ].join(', ')
      primitivesCode += `const { ${factories} } = createSlotRecipeContext(${recipe})\n\n`
    }

    /**
     * Factory options for a member: `forwardProps` (CSS-named props kept for Ark) and
     * `defaultProps` (passed to Ark unless the caller sets them); '' when neither
     */
    const forwardOptions = (member: string) => {
      const options: string[] = []
      const forwarded = forwardProps[member]
      if (forwarded?.length) {
        options.push(
          `forwardProps: [${forwarded.map((p) => `'${p}'`).join(', ')}]`,
        )
      }
      const defaults = Object.entries(defaultProps[member] ?? {})
      if (defaults.length > 0) {
        const entries = defaults.map(
          ([prop, value]) =>
            `${propertyKey(prop)}: ${defaultPropSource(value)}`,
        )
        options.push(`defaultProps: { ${entries.join(', ')} }`)
      }
      return options.length > 0 ? `{ ${options.join(', ')} }` : ''
    }

    /** `root` provides the recipe; other parts consume it from context */
    const styled = (member: string, slot: string, isRoot: boolean) => {
      const arkPart = `${ark}.${member}`
      const options = forwardOptions(member)
      if (isRoot && rootProvider) {
        if (!recipe) return arkPart
        return `withRootProvider(${arkPart}${options ? `, ${options}` : ''})`
      }
      if (!recipe)
        return `styled(${arkPart}${options ? `, {}, ${options}` : ''})`
      // A part listed in `providers` renders outside Root and provides the recipe itself
      const provides = isRoot || isProvider(slot) || isProvider(member)
      return `${provides ? 'withProvider' : 'withContext'}(${arkPart}, '${slot}'${options ? `, ${options}` : ''})`
    }

    const members = [
      ...parts.map((part) => ({
        exportKey: capitalize(part),
        code: styled(capitalize(part), part, part === 'root'),
      })),
      // `RootProvider` is a `Root` driven by an external `useX()`; contexts render
      // props; any other member has no recipe slot
      ...arkMembers.map((member) => ({
        exportKey: member,
        code:
          member === 'RootProvider'
            ? styled(member, 'root', true)
            : isProvider(member)
              ? styled(member, providerSlot(member)!, false)
              : memberSlots[member]
                ? styled(member, memberSlots[member], false)
                : member.endsWith('Context')
                  ? `${ark}.${member}`
                  : `styled(${ark}.${member}${forwardOptions(member) ? `, {}, ${forwardOptions(member)}` : ''})`,
      })),
    ]

    // Cerberus recipe slots outside the Ark anatomy (Popover.Header…), with the same
    // data-scope/data-part attributes as the Ark parts around them
    for (const [slot, element] of Object.entries(elementParts)) {
      const attrs = `{ 'data-scope': '${arkKey}', 'data-part': '${toKebabCase(slot)}' }`
      members.push({
        exportKey: capitalize(slot),
        code: `withContext(ark.${element}, '${slot}', { defaultProps: ${attrs} })`,
      })
    }

    for (const { exportKey, code } of members) {
      const partName = `${name}${exportKey}`
      if (collectionGeneric.includes(exportKey)) {
        // withProvider erases Ark's `<T extends CollectionItem>`: swap the machine props
        // for the generic ones and restore the generic call signature
        const base = `Ark${arkName}${exportKey}BaseProps`
        primitivesCode += `// ${partName} -----------------------------------------------------\n\n`
        primitivesCode += `const ${partName}Styled = ${code}\n`
        primitivesCode += `export type ${partName}Props<T extends CollectionItem = CollectionItem> = Omit<ComponentProps<typeof ${partName}Styled>, keyof ${base}<CollectionItem>> & ${base}<T>\n`
        primitivesCode += `export const ${partName} = ${partName}Styled as unknown as <T extends CollectionItem>(props: ${partName}Props<T>) => ReactElement\n\n`
        continue
      }
      const supplied = patchable[exportKey]
      if (supplied?.length) {
        // The abstraction supplies these props to a patch child; `*Props` stays strict
        const keys = supplied.map((p) => `'${p}'`).join(' | ')
        const names = supplied.map((p) => `\`${p}\``).join(', ')
        primitivesCode += `// ${partName} -----------------------------------------------------\n\n`
        primitivesCode += `const ${partName}Styled = ${code}\n`
        primitivesCode += `export type ${partName}Props = ComponentProps<typeof ${partName}Styled>\n`
        primitivesCode += `/** As a patch child of a ${name} abstraction, ${names} may be omitted: the abstraction supplies ${supplied.length > 1 ? 'them' : 'it'}. */\n`
        primitivesCode += `export const ${partName} = ${partName}Styled as Patchable<typeof ${partName}Styled, ${keys}>\n\n`
        continue
      }
      primitivesCode += `// ${partName} -----------------------------------------------------\n\n`
      primitivesCode += `export type ${partName}Props = ComponentProps<typeof ${partName}>\n`
      primitivesCode += `export const ${partName} = ${code}\n\n`
    }

    files.push({
      path: join(outputDir, 'primitives.ts'),
      content: primitivesCode,
    })
  }

  // --- Generate api.ts ---
  let apiCode = GENERATED_HEADER

  const abstractionsByFile = new Map<
    string,
    { values: string[]; types: string[] }
  >()

  for (const abs of abstractions) {
    const entry = abstractionsByFile.get(abs.file) ?? { values: [], types: [] }
    entry.values.push(`${name}${abs.name}`)
    if (abs.types?.length) {
      entry.types.push(...abs.types)
    }
    abstractionsByFile.set(abs.file, entry)
  }

  for (const [file, { values, types: absTypes }] of abstractionsByFile) {
    if (values.length) {
      apiCode += `import { ${values.join(', ')} } from './${file}'\n`
    }
    if (absTypes.length) {
      apiCode += `export type { ${absTypes.join(', ')} } from './${file}'\n`
    }
  }

  const members = [
    ...parts.map(capitalize),
    ...(isArkUI ? arkMembers : []),
    ...(isArkUI ? Object.keys(elementParts).map(capitalize) : []),
  ]
  if (members.length > 0) {
    apiCode += `import {\n`
    for (const member of members) {
      apiCode += `  ${name}${member},\n`
    }
    apiCode += `} from './primitives'\n\n`
  }

  const primitiveTypes = isArkUI
    ? [...members.map((member) => `${name}${member}Props`), ...types]
    : [...types]

  if (primitiveTypes.length > 0) {
    apiCode += `export type {\n`
    for (const typeName of primitiveTypes) {
      apiCode += `  ${typeName},\n`
    }
    apiCode += `} from './primitives'\n\n`
  }

  // --- Generate Rust-Style JSDoc (Aligned with Pure JSX Part Overrides) ---
  const docUrl = `${REF_URL}/${docsSlug}`
  const formattedDesc = description
    .trim()
    .split('\n')
    .map((line) => (line.trim() ? ` * ${line}` : ' *'))
    .join('\n')

  let jsDoc = `/**\n`
  jsDoc += ` * ## ${name}\n`
  jsDoc += ` *\n`
  jsDoc += `${formattedDesc}\n`
  jsDoc += ` *\n`
  jsDoc += ` * Customize ${name} using Panda style props, direct JSX child part overrides on abstractions, or the low-level primitives for full structural control.\n`
  jsDoc += ` *\n`
  jsDoc += ` * ## Parts\n`
  jsDoc += ` *\n`
  jsDoc += ` * | Part | Kind | Description |\n`
  jsDoc += ` * |------|------|-------------|\n`

  for (const part of parts) {
    const exportKey = part === 'root' ? 'Root' : capitalize(part)
    const desc = describe(
      part,
      part !== 'root'
        ? `The ${toWords(part)} element of the ${name} component.`
        : rootProvider
          ? `Provides the ${name} context to its parts; renders no element.`
          : `The root element of the ${name} component.`,
    )
    jsDoc += ` * | \`${exportKey}\` | Primitive | ${desc} |\n`
  }

  for (const member of isArkUI ? arkMembers : []) {
    const desc = describe(
      member,
      member === 'RootProvider'
        ? `A \`Root\` driven by state from Ark's \`use${arkName}()\`.`
        : memberSlots[member]
          ? `The ${toWords(member)} element of the ${name} component, styled with the \`${memberSlots[member]}\` slot.`
          : providers.includes(member)
            ? `A \`${capitalize(providerSlot(member)!)}\` driven by state from Ark's \`use${arkName}${capitalize(providerSlot(member)!)}()\`.`
            : member.endsWith('Context')
              ? `Exposes the ${name} ${member === 'Context' ? '' : `${toWords(member.replace(/Context$/, ''))} `}state to a render function.`
              : `The ${toWords(member)} element of the ${name} component. It has no recipe slot.`,
    )
    jsDoc += ` * | \`${member}\` | Primitive | ${desc} |\n`
  }

  for (const slot of isArkUI ? Object.keys(elementParts) : []) {
    const desc = describe(
      slot,
      `The ${toWords(slot)} element of the ${name} component (a Cerberus recipe slot outside the Ark anatomy).`,
    )
    jsDoc += ` * | \`${capitalize(slot)}\` | Primitive | ${desc} |\n`
  }

  for (const abs of abstractions) {
    jsDoc += ` * | \`${abs.name}\` | Abstraction | ${abs.description} |\n`
  }

  jsDoc += ` *\n`
  jsDoc += ` * @example\n`
  jsDoc += ` * \`\`\`tsx\n`
  jsDoc += ` * import { ${name} } from '@cerberus/react'\n`
  jsDoc += ` *\n`
  for (const line of componentExample(entry).split('\n')) {
    jsDoc += line ? ` * ${line}\n` : ` *\n`
  }
  jsDoc += ` * \`\`\`\n`
  jsDoc += ` *\n`
  jsDoc += ` * ## Reference\n`
  jsDoc += ` *\n`
  jsDoc += ` * @see [${name} Docs](${docUrl})\n`
  jsDoc += ` */\n`

  apiCode += jsDoc

  const defaultAbstraction = abstractions.find((abs) => abs.isDefaultExport)
  const fallbackRoot = parts.includes('root')
    ? `${name}Root`
    : `${name}${capitalize(parts[0])}`
  const assignTarget = defaultAbstraction
    ? `${name}${defaultAbstraction.name}`
    : fallbackRoot

  apiCode += `export const ${name} = Object.assign(${assignTarget}, {\n`

  for (const member of members) {
    apiCode += `  ${member}: ${name}${member},\n`
  }

  for (const abs of abstractions) {
    apiCode += `  ${abs.name}: ${name}${abs.name},\n`
  }

  apiCode += `})\n`

  for (const { from, values = [], types: exportTypes = [] } of exports) {
    if (values.length) {
      apiCode += `\nexport { ${values.join(', ')} } from '${from}'`
    }
    if (exportTypes.length) {
      apiCode += `\nexport type { ${exportTypes.join(', ')} } from '${from}'`
    }
  }
  if (exports.length) apiCode += `\n`

  files.push({ path: join(outputDir, 'api.ts'), content: apiCode })
  files.push({
    path: join(outputDir, 'index.ts'),
    content: `${GENERATED_HEADER}export * from './api'\n`,
  })
  return files
}

async function main(): Promise<number> {
  const check = process.argv.includes('--check')
  // `--only <key>` (repeatable) generates just those components, e.g. while migrating
  const only = process.argv.flatMap((arg, i, argv) =>
    argv[i - 1] === '--only' ? [arg] : [],
  )
  const diagnostics = new Diagnostics()
  const entries = loadManifest(
    await loadConfigs(undefined, only.length > 0 ? only : undefined),
    diagnostics,
  )
  diagnostics.print()
  if (diagnostics.errorCount > 0) return 1

  const files = entries.flatMap(generateComponentAPI)
  const { stale } = await emitFiles(files, { check })
  reportStale(stale, 'pnpm generate:api')
  if (stale.length > 0) return 1

  console.log(
    check
      ? '✅ Component APIs are up to date.'
      : `🎉 Generated APIs for ${entries.map((e) => e.name).join(', ')}`,
  )
  return 0
}

if (import.meta.main) {
  main().then(
    (code) => process.exit(code),
    (err) => {
      console.error(err)
      process.exit(1)
    },
  )
}
